<script setup lang="ts">
import {ref,reactive,computed,onMounted} from 'vue';import {api,mutate,types,text,date,useDirty,useTask,type DTO,type Page} from './shared';import {download} from '../../shared/api/client';import PageState from './PageState.vue';import Pager from './Pager.vue';
const {busy,error,notice,run}=useTask(),type=ref('platform_account'),label=ref(''),csv=ref(''),headers=ref<string[]>([]),mapping=reactive<Record<string,string>>({}),batch=ref<DTO<'Stage2BatchView'>>(),skip=ref<number[]>([]),batches=ref<DTO<'Stage2BatchView'>[]>([]),page=ref(1),total=ref(0),more=ref(false);
const fields:Record<string,string>={name:'名称',provider_name:'提供方',purpose:'用途',platform_id:'已有平台 ID',owning_department_id:'已有部门 ID',source_note:'信息来源',domain_name:'域名',expires_on:'到期日',endpoint:'访问地址',external_instance_id:'外部实例标识'};
useDirty(()=>Boolean(csv.value)&&batch.value?.status!=='committed',()=>busy.value);
async function load(){await run(async()=>{const data=await api.get<Page<DTO<'Stage2BatchView'>>>('/imports?page='+page.value);batches.value=data.items;total.value=data.pagination.total;more.value=data.pagination.has_next;});}onMounted(load);
function parseHeader(s:string){const row:string[]=[];let value='',quoted=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted)break;else value+=c;}row.push(value);return row.map(x=>x.replace(/^\uFEFF/,'').trim());}
async function choose(event:Event){await run(async()=>{const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('CSV 不能超过 5 MiB');csv.value=await file.text();label.value=file.name;headers.value=parseHeader(csv.value);Object.keys(mapping).forEach(k=>delete mapping[k]);headers.value.forEach(h=>mapping[h]=h in fields?h:'');batch.value=undefined;skip.value=[];});}
async function preview(){await run(async()=>{if(headers.value.some(h=>!mapping[h]))throw new Error('请为每个 CSV 列指定唯一目标字段；未支持的列应先从文件中移除。');batch.value=await mutate<DTO<'Stage2BatchView'>>('/imports/preview',{type_code:type.value,label:label.value,csv_content:csv.value,mapping});skip.value=[];await load();});}
async function commit(){await run(async()=>{if(!batch.value)return;batch.value=await mutate<DTO<'Stage2BatchView'>>(`/imports/${batch.value.id}/actions/commit`,{expected_version:batch.value.version,skip_rows:skip.value});csv.value='';notice.value='已按确认的预览结果导入。';await load();});}
const allowed=computed(()=>batch.value?.status==='preview'&&batch.value.results.every(r=>r.status==='ready'||skip.value.includes(r.row_number))&&batch.value.results.some(r=>r.status==='ready'&&!skip.value.includes(r.row_number)));
</script>
<template><header class="page-heading"><div><h1>导入资源</h1><p>选择类型与字段映射 → 校验预览 → 明确跳过问题行 → 确认导入。不会自动合并同名记录。</p></div><RouterLink to="/resources" class="btn-secondary">返回清单</RouterLink></header><PageState :busy="busy" :error="error" :notice="notice" @retry="load"/><section class="feishu-section mb-4 p-4"><form class="space-y-3" @submit.prevent="preview"><div class="flex flex-wrap gap-3"><label class="min-w-0 flex-1"><span class="admin-form-label">统一资源类型</span><select v-model="type" class="admin-field" :disabled="busy||Boolean(batch)"><option v-for="(name,key) in types" :value="key">{{name}}</option></select></label><label class="min-w-0 flex-1"><span class="admin-form-label">批次名称</span><input v-model="label" class="admin-field" required maxlength="200" :disabled="busy||Boolean(batch)"></label></div><div class="flex flex-wrap items-center gap-2"><button class="btn-secondary" type="button" :disabled="busy" @click="run(()=>download('/imports/template?type_code='+type,'资源导入模板.csv'))">下载该类型模板</button><input type="file" accept=".csv,text/csv" class="min-w-0 max-w-full text-xs" aria-label="选择 CSV 文件" :disabled="busy" @change="choose"></div><p class="text-xs text-gray-500">最多 1000 行，5 MiB；不支持密码、API Key 或任意动态字段。可不填写平台等上游引用。</p><div v-if="headers.length&&!batch" class="grid gap-2 sm:grid-cols-2"><label v-for="h in headers" :key="h" class="flex items-center gap-2 text-xs"><span class="w-1/3 break-words">{{h}}</span><select v-model="mapping[h]" class="admin-field" required :disabled="busy||Boolean(batch)"><option value="">请选择目标字段</option><option v-for="(n,k) in fields" :value="k">{{n}}</option></select></label></div><div class="flex gap-2"><button v-if="csv&&!batch" class="btn-primary" :disabled="busy">校验并预览</button><button v-if="batch" class="btn-secondary" type="button" @click="batch=undefined;skip=[]">重新选择 / 修正文件</button></div></form></section><section v-if="batch" class="feishu-section mb-4"><div class="toolbar justify-between"><div><h2 class="text-sm font-medium">{{batch.label}} · {{text(batch.status)}}</h2><p class="mt-1 text-xs text-gray-500">预览有效至 {{date(batch.expires_at)}}；校验预览不创建正式资源。</p></div><button class="btn-secondary" :disabled="busy" @click="run(()=>download(`/imports/${batch!.id}/errors`,'导入问题行.csv'))">下载错误报告</button></div><div class="admin-table-scroll"><table class="feishu-table min-w-[520px]"><thead><tr><th>跳过</th><th>行</th><th>状态</th><th>校验 / 结果</th></tr></thead><tbody><tr v-for="r in batch.results" :key="r.row_number"><td><input v-if="batch.status==='preview'" v-model="skip" type="checkbox" :value="r.row_number" :aria-label="'跳过第'+r.row_number+'行'"></td><td>{{r.row_number}}</td><td>{{text(r.status)}}</td><td><p>{{r.message??'校验通过'}}</p><RouterLink v-if="r.resource_id" :to="'/resources/'+r.resource_id" class="text-link">查看已创建资源</RouterLink><div v-for="candidate in r.candidate_ids" :key="candidate"><RouterLink :to="'/resources/'+candidate" class="text-link">查看同名候选</RouterLink></div></td></tr></tbody></table></div><footer v-if="batch.status==='preview'" class="flex flex-wrap items-center justify-between gap-3 border-t p-3 text-xs"><span>已明确跳过 {{skip.length}} 行；其余记录原子导入。</span><button class="btn-primary" :disabled="busy||!allowed" @click="commit">确认导入</button></footer></section><section class="feishu-section"><h2 class="border-b p-3 text-sm font-medium">我的导入批次</h2><div v-for="b in batches" :key="b.id" class="flex items-center justify-between gap-2 border-b px-3 py-3 text-xs"><span>{{b.label}} · {{text(b.status)}} · {{date(b.created_at)}}</span><button class="text-link" @click="run(async()=>{batch=await api.get<DTO<'Stage2BatchView'>>('/imports/'+b.id);skip=[];})">查看预览与结果</button></div><Pager :page="page" :total="total" :more="more" @change="page=$event;load()"/></section></template>
